{
  "findings": [
    {
      "ref": "[D538]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child in multiplayer, but it is not on by default and can be turned off.",
      "stance": "risk",
      "quote": "When joining a multiplayer server, Minecraft will display a disclaimer telling your child that they may be exposed to open chatrooms that have not been rated (and therefore contain language or content suitable for all ages). Through Minecraft itself players can only communicate through a text chat, other applications such as Skype or Discord can allow your child to audibly talk with friends."
    },
    {
      "ref": "[D538]",
      "area": "money",
      "claim": "A parent reports that the game offers optional purchases such as texture packs, skin packs, and Realms subscriptions, but there are no compulsory subscription fees or hidden costs.",
      "stance": "neutral",
      "quote": "Once you have bought Minecraft you can then play the game without any compulsory additional spend, such as any kind of subscription fees or hidden costs. However, there are certain additional features that can be purchased. * Texture and skin packs: Texture packs are buyable ‘packs’ that change the look of your Minecraft blocks, with the literal textures of the world being changed to be brighter, darker or even different colours. There are hundreds of texture packs online, with some being available for free for platforms such as home computer, while others are buyable from Minecraft. Skin packs are the same, only they change the appearance of your character. * Minecraft Realms: Minecraft Realms is an online membership for Minecraft that allows you to operate your own multiplayer servers. While basic Minecraft allows for only one player per world, Realms allows for multiple players to play within the same game no matter where they are in the world. These realms are completely controllable by you, allowing you to change the difficulty and the look and feel of the game. * Online Multiplayer: For certain consoles such as Nintendo Switch, online multiplayer is only available to those who have an online membership. This doesn’t apply to all versions of Minecraft."
    },
    {
      "ref": "[D538]",
      "area": "data",
      "claim": "A parent reports that the game collects account information including birthday for age restrictions and may share data with third parties for advertising, but the privacy policy linked can be used to delete data.",
      "stance": "risk",
      "quote": "If the game registers that you are under 13 then certain elements are locked, including making in-game purchases. However, it is very easy for a child to be aware of these restrictions and choose to enter a birth year that allows them full access to all the features. The official Minecraft website has a [useful guide to online safety](https://www.minecraft.net/en-us/article/minecraft-multiplayer-server-safety) when using Minecraft, which you should check out if you are still unsure about whether to allow your child to play on multiplayer servers."
    },
    {
      "ref": "[D538]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate requires a birthday entry and locks purchases for under‑13 accounts, but children can easily bypass it by entering a different birth year.",
      "stance": "risk",
      "quote": "If the game registers that you are under 13 then certain elements are locked, including making in-game purchases. However, it is very easy for a child to be aware of these restrictions and choose to enter a birth year that allows them full access to all the features."
    },
    {
      "ref": "[D538]",
      "area": "content",
      "claim": "A parent reports that the game contains mild cartoonish violence with no blood, and monsters disappear in a puff of smoke, but the combat is optional and can be turned off.",
      "stance": "neutral",
      "quote": "The combat within the game is very simple, with damage being taken off of your health bar if you are hit by a monster or their weapon (and vice versa if you are attacking a monster). If you choose to fight, hearts appear around the monster to show damage is being taken instead of any visible injuries or blood. The only truly ‘scary’ element to the game could arguably be the night-time and the audio of unseen monsters (with zombies making stereotypical moans and skeletons rattling), but this can easily be fixed by turning the audio of the monsters down in the settings."
    },
    {
      "ref": "[D538]",
      "area": "developer_record",
      "claim": "A parent reports that there is no mention of fines, breaches, lawsuits or regulatory actions against the developer in the provided text.",
      "stance": "neutral",
      "quote": "The provided text does not mention any fines, breaches, lawsuits or regulatory actions against the developer."
    }
  ]
}
